-- ====================================================================
-- ESQUEMA COMPLETO Y MIGRACIÓN HISTÓRICA PARA SUPABASE (HEMPC / NUCLEUS)
-- Incluye: Usuarios, Socios, Campos/Sitios, Parcelas y Ensayos de Campo
-- de las campañas 2024/2025 y 2025/2026
-- ====================================================================

-- 1. TABLA: PLATFORM_SETTINGS
CREATE TABLE IF NOT EXISTS public.platform_settings (
    id TEXT PRIMARY KEY DEFAULT 'default',
    app_name TEXT DEFAULT 'HempC',
    app_logo TEXT DEFAULT '',
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. TABLA: USERS
CREATE TABLE IF NOT EXISTS public.users (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    email TEXT UNIQUE NOT NULL,
    password TEXT DEFAULT 'admin',
    role TEXT DEFAULT 'technician',
    member_type TEXT DEFAULT 'Socio_Productor',
    organization_name TEXT,
    job_title TEXT,
    phone TEXT,
    avatar TEXT,
    is_network_member BOOLEAN DEFAULT TRUE,
    client_id TEXT,
    structure_role TEXT,
    assigned_plot_ids JSONB DEFAULT '[]'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3. TABLA: CLIENTS (SOCIOS DE RED Y ORGANIZACIONES)
CREATE TABLE IF NOT EXISTS public.clients (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    type TEXT,
    contact_name TEXT,
    contact_phone TEXT,
    email TEXT,
    address TEXT,
    total_hectares NUMERIC DEFAULT 0,
    is_network_member BOOLEAN DEFAULT TRUE,
    membership_level TEXT DEFAULT 'Activo',
    contract_date TEXT,
    cuit TEXT,
    related_user_id TEXT,
    location_id TEXT,
    coordinates JSONB DEFAULT '{}'::jsonb,
    team_user_ids JSONB DEFAULT '[]'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 4. TABLA: LOCATIONS (CAMPOS Y SITIOS PRODUCTIVOS)
CREATE TABLE IF NOT EXISTS public.locations (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    site_type TEXT,
    status TEXT DEFAULT 'Activo',
    active_campaigns JSONB DEFAULT '[]'::jsonb,
    province TEXT,
    city TEXT,
    address TEXT,
    soil_type TEXT,
    climate TEXT,
    responsible_person TEXT,
    responsible_ids JSONB DEFAULT '[]'::jsonb,
    client_id TEXT,
    coordinates JSONB DEFAULT '{}'::jsonb,
    capacity_ha NUMERIC DEFAULT 0,
    irrigation_system TEXT,
    ariccame_license_number TEXT,
    ariccame_license_category TEXT,
    ariccame_license_status TEXT,
    renspa_number TEXT,
    cadastral_id TEXT,
    land_tenure_type TEXT,
    owner_name TEXT,
    owner_type TEXT,
    sowing_declaration_ha NUMERIC DEFAULT 0,
    sowing_declaration_id TEXT,
    security_measures JSONB DEFAULT '[]'::jsonb,
    polygon JSONB DEFAULT '[]'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 5. TABLA: PROJECTS (CAMPAÑAS Y PROGRAMAS AGRONÓMICOS)
CREATE TABLE IF NOT EXISTS public.projects (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    description TEXT,
    status TEXT DEFAULT 'En Curso',
    start_date TEXT,
    campaign TEXT NOT NULL,
    objective_type TEXT,
    target_yield_tn NUMERIC DEFAULT 0,
    budget_usd NUMERIC DEFAULT 0,
    director_id TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 6. TABLA: VARIETIES (CATÁLOGO GENÉTICO INASE)
CREATE TABLE IF NOT EXISTS public.varieties (
    id TEXT PRIMARY KEY,
    supplier_id TEXT,
    name TEXT NOT NULL,
    origin TEXT,
    category TEXT,
    usage TEXT,
    cycle_days NUMERIC DEFAULT 120,
    expected_thc NUMERIC DEFAULT 0.1,
    optimal_density TEXT,
    thc_expected NUMERIC,
    cbd_expected NUMERIC,
    cbg_expected NUMERIC,
    cannabinoid_profile TEXT,
    certified_license_number TEXT,
    biomass_yield_per_ha NUMERIC,
    grain_yield_per_ha NUMERIC,
    description TEXT,
    is_commercial BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 7. TABLA: PLOTS (PARCELAS DE CULTIVO DE LA CAMPAÑA ANTERIOR Y ACTUAL)
CREATE TABLE IF NOT EXISTS public.plots (
    id TEXT PRIMARY KEY,
    location_id TEXT NOT NULL,
    project_id TEXT,
    variety_id TEXT,
    name TEXT NOT NULL,
    seed_batch_id TEXT,
    type TEXT DEFAULT 'Ensayo',
    surface_area NUMERIC DEFAULT 0,
    surface_unit TEXT DEFAULT 'ha',
    density NUMERIC DEFAULT 0,
    status TEXT DEFAULT 'Activa',
    campaign TEXT NOT NULL,
    active_campaigns JSONB DEFAULT '[]'::jsonb,
    sowing_date TEXT,
    owner_name TEXT,
    irrigation_type TEXT,
    coordinates JSONB DEFAULT '{}'::jsonb,
    polygon JSONB DEFAULT '[]'::jsonb,
    observations TEXT,
    current_phenological_stage TEXT,
    used_seed_value NUMERIC DEFAULT 0,
    used_seed_unit TEXT DEFAULT 'kg',
    color TEXT DEFAULT '#10b981',
    stage_history JSONB DEFAULT '[]'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 8. TABLA: TRIAL_RECORDS (ENSAYOS DE CAMPO, FENOLOGÍA & MONITOREO)
CREATE TABLE IF NOT EXISTS public.trial_records (
    id TEXT PRIMARY KEY,
    plot_id TEXT NOT NULL,
    date TEXT NOT NULL,
    time TEXT,
    stage TEXT,
    temperature NUMERIC,
    humidity NUMERIC,
    plant_height NUMERIC,
    plants_per_meter NUMERIC,
    uniformity NUMERIC,
    vigor NUMERIC,
    lodging NUMERIC,
    bird_damage NUMERIC,
    diseases_score NUMERIC,
    pests_score NUMERIC,
    harvest_plant_count NUMERIC,
    seed_yield NUMERIC,
    seed_quality_germination NUMERIC,
    seed_quality_non_conformity NUMERIC,
    stem_weight NUMERIC,
    flowering_date TEXT,
    harvest_date TEXT,
    notes TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 9. TABLA: HYDRIC_RECORDS (BALANCE HÍDRICO & REGISTROS PLUVIOMÉTRICOS)
CREATE TABLE IF NOT EXISTS public.hydric_records (
    id TEXT PRIMARY KEY,
    location_id TEXT NOT NULL,
    plot_id TEXT,
    date TEXT NOT NULL,
    time TEXT,
    end_time TEXT,
    type TEXT NOT NULL,
    amount_mm NUMERIC NOT NULL,
    notes TEXT,
    created_by TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 10. TABLA: TASKS (LABORES AGRÍCOLAS & ÓRDENES DE TRABAJO)
CREATE TABLE IF NOT EXISTS public.tasks (
    id TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    description TEXT,
    status TEXT DEFAULT 'Pendiente',
    priority TEXT DEFAULT 'Media',
    assigned_to_ids JSONB DEFAULT '[]'::jsonb,
    due_date TEXT NOT NULL,
    execution_date TEXT,
    plot_id TEXT,
    created_by TEXT,
    operator TEXT,
    labor_type TEXT,
    target_stage TEXT,
    advances_phenological_stage BOOLEAN DEFAULT FALSE,
    new_phenological_stage TEXT,
    direct_cost_usd NUMERIC DEFAULT 0,
    machinery JSONB DEFAULT '{}'::jsonb,
    weather_conditions JSONB DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 11. TABLA: STORAGE_POINTS (CENTROS DE ACOPIO & DEPÓSITOS)
CREATE TABLE IF NOT EXISTS public.storage_points (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    node_code TEXT,
    type TEXT,
    address TEXT,
    city TEXT,
    province TEXT,
    coordinates JSONB DEFAULT '{}'::jsonb,
    responsible_user_id TEXT,
    client_id TEXT,
    capacity_kg NUMERIC DEFAULT 0,
    current_stock_kg NUMERIC DEFAULT 0,
    temperature_c NUMERIC,
    humidity_pct NUMERIC,
    responsible_person TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 12. TABLA: SUPPLIERS (PROVEEDORES HOMOLOGADOS)
CREATE TABLE IF NOT EXISTS public.suppliers (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    cuit TEXT,
    contact_name TEXT,
    email TEXT,
    phone TEXT,
    address TEXT,
    province TEXT,
    category TEXT,
    is_homologated BOOLEAN DEFAULT TRUE,
    rating NUMERIC DEFAULT 5.0,
    observations TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 13. TABLA: SEED_BATCHES (LOTES DE SEMILLA & COSECHA CON TRAZABILIDAD)
CREATE TABLE IF NOT EXISTS public.seed_batches (
    id TEXT PRIMARY KEY,
    variety_id TEXT NOT NULL,
    supplier_id TEXT,
    batch_code TEXT NOT NULL,
    label_serial_number TEXT,
    category TEXT,
    analysis_date TEXT,
    purity NUMERIC,
    germination NUMERIC,
    initial_quantity NUMERIC DEFAULT 0,
    remaining_quantity NUMERIC DEFAULT 0,
    unit TEXT DEFAULT 'kg',
    storage_point_id TEXT,
    is_active BOOLEAN DEFAULT TRUE,
    origin_plot_id TEXT,
    origin_campaign TEXT,
    harvest_date TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 14. TABLA: SEED_MOVEMENTS (REMITOS & MOVIMIENTOS LOGÍSTICOS)
CREATE TABLE IF NOT EXISTS public.seed_movements (
    id TEXT PRIMARY KEY,
    batch_id TEXT NOT NULL,
    client_id TEXT,
    target_location_id TEXT,
    target_storage_point_id TEXT,
    quantity NUMERIC NOT NULL,
    unit TEXT DEFAULT 'kg',
    date TEXT NOT NULL,
    movement_type TEXT,
    origin_supplier_id TEXT,
    origin_storage_point_id TEXT,
    target_plot_id TEXT,
    reason TEXT,
    operator TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 15. TABLA: RESOURCES (INSUMOS, FERTILIZANTES Y MAQUINARIA)
CREATE TABLE IF NOT EXISTS public.resources (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    type TEXT NOT NULL,
    unit TEXT NOT NULL,
    cost_per_unit NUMERIC DEFAULT 0,
    stock NUMERIC DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 16. TABLA: OPERATIONAL_EXPENSES (COSTOS OPERATIVOS Y AUDITORÍA ECONÓMICA)
CREATE TABLE IF NOT EXISTS public.operational_expenses (
    id TEXT PRIMARY KEY,
    campaign TEXT NOT NULL,
    date TEXT NOT NULL,
    scope TEXT NOT NULL,
    plot_id TEXT,
    plot_name TEXT,
    location_name TEXT,
    socio_id TEXT,
    socio_name TEXT,
    category TEXT NOT NULL,
    concept TEXT NOT NULL,
    quantity NUMERIC DEFAULT 1,
    unit TEXT DEFAULT 'global',
    unit_cost NUMERIC DEFAULT 0,
    total_cost NUMERIC DEFAULT 0,
    total_cost_usd NUMERIC DEFAULT 0,
    currency TEXT DEFAULT 'USD',
    payment_method TEXT,
    fiscal_doc_number TEXT,
    audit_status TEXT DEFAULT 'Aprobado',
    recorded_by TEXT,
    status TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 17. TABLA: FIELD_LOGS (BITÁCORA MULTIMEDIA)
CREATE TABLE IF NOT EXISTS public.field_logs (
    id TEXT PRIMARY KEY,
    plot_id TEXT NOT NULL,
    date TEXT NOT NULL,
    note TEXT NOT NULL,
    photo_urls JSONB DEFAULT '[]'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- HABILITACIÓN DE POLÍTICAS RLS (Row Level Security) PERMISIVAS
-- Para permitir lectura/escritura tanto con service_role como con anon key
DO 1115 
DECLARE
    tbl text;
BEGIN
    FOR tbl IN 
        SELECT unnest(ARRAY[
            'platform_settings', 'users', 'clients', 'locations', 'projects',
            'varieties', 'plots', 'trial_records', 'hydric_records', 'tasks',
            'storage_points', 'suppliers', 'seed_batches', 'seed_movements',
            'resources', 'operational_expenses', 'field_logs'
        ])
    LOOP
        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY;', tbl);
        EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I;', 'permit_all_' || tbl, tbl);
        EXECUTE format('CREATE POLICY %I ON public.%I FOR ALL USING (true) WITH CHECK (true);', 'permit_all_' || tbl, tbl);
    END LOOP;
END 1115;


